#include <boost/multiprecision/cpp_int.hpp>
#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using boost::multiprecision::cpp_int;
using namespace std;

static int hexval(char c){
    if(c>='0'&&c<='9') return c-'0';
    if(c>='a'&&c<='f') return 10+c-'a';
    if(c>='A'&&c<='F') return 10+c-'A';
    return -1;
}
static bool is_prime_int(int p){
    if(p<2) return false;
    for(int q=2; 1LL*q*q<=p; ++q) if(p%q==0) return false;
    return true;
}
static bool bareiss_spd(vector<vector<cpp_int>> A, unsigned &final_bits){
    const int n=A.size();
    cpp_int prev=1;
    for(int k=0;k<n-1;k++){
        cpp_int pivot=A[k][k];
        if(pivot<=0) return false;
        for(int i=k+1;i<n;i++){
            cpp_int aik=A[i][k];
            for(int j=i;j<n;j++){
                cpp_int num=A[i][j]*pivot-aik*A[k][j];
                if(num%prev!=0) return false;
                cpp_int val=num/prev;
                A[i][j]=val;
                A[j][i]=val;
            }
        }
        prev=pivot;
    }
    if(A[n-1][n-1]<=0) return false;
    final_bits=boost::multiprecision::msb(A[n-1][n-1])+1;
    return true;
}
int main(){
    const int p=1601, t=26, scale=8;
    const string whex=R"PAYLOAD()PAYLOAD";
    if(!is_prime_int(p) || p%4!=1){ cerr<<"PRIME_OR_CONGRUENCE_FAIL\n"; return 1; }

    vector<char> qr(p,0);
    for(int x=1;x<p;x++) qr[(1LL*x*x)%p]=1;
    vector<int> V;
    for(int x=0;x<p;x++) if(qr[x] && qr[(x-1+p)%p]) V.push_back(x);
    int n=V.size();
    if(n!=(p-5)/4 || n!=399){ cerr<<"LOCALIZATION_SIZE_FAIL\n"; return 2; }

    vector<int> idx(p,-1);
    for(int i=0;i<n;i++) idx[V[i]]=i;
    vector<int> tau(n,-1), fixed;
    for(int i=0;i<n;i++){
        tau[i]=idx[(1-V[i]+p)%p];
        if(tau[i]<0){ cerr<<"TAU_DOMAIN_FAIL\n"; return 3; }
        if(tau[i]==i) fixed.push_back(i);
    }
    if(fixed.size()!=1){ cerr<<"TAU_FIXED_FAIL\n"; return 4; }

    vector<vector<long long>> B(n, vector<long long>(n,0));
    for(int i=0;i<n;i++) B[i][i]=scale*(t-1);
    for(int i=0;i<n;i++) for(int j=i+1;j<n;j++){
        int d=(V[i]-V[j]+p)%p;
        if(qr[d]) B[i][j]=B[j][i]=-scale;
    }
    vector<vector<char>> seen(n, vector<char>(n,0));
    size_t pos=0; int orbit_count=0;
    for(int i=0;i<n;i++) for(int j=i+1;j<n;j++){
        int d=(V[i]-V[j]+p)%p;
        if(qr[d] || seen[i][j]) continue;
        if(pos>=whex.size()){ cerr<<"PAYLOAD_SHORT\n"; return 5; }
        int q=hexval(whex[pos++]);
        if(q<=0){ cerr<<"PAYLOAD_HEX_FAIL\n"; return 6; }
        int a=tau[i], b=tau[j]; if(a>b) swap(a,b);
        int dd=(V[a]-V[b]+p)%p;
        if(qr[dd]){ cerr<<"TAU_NONEDGE_FAIL\n"; return 7; }
        B[i][j]=B[j][i]=q;
        B[a][b]=B[b][a]=q;
        seen[i][j]=seen[j][i]=1;
        seen[a][b]=seen[b][a]=1;
        orbit_count++;
    }
    if(pos!=whex.size() || orbit_count!=20000){ cerr<<"ORBIT_COUNT_FAIL\n"; return 8; }

    long long edge_pairs=0, nonedge_pairs=0;
    for(int i=0;i<n;i++) for(int j=i+1;j<n;j++){
        int d=(V[i]-V[j]+p)%p;
        if(qr[d]){ edge_pairs++; if(B[i][j]!=-scale) return 9; }
        else { nonedge_pairs++; if(!seen[i][j] || B[i][j]<=0 || B[i][j]>15) return 10; }
        if(B[tau[i]][tau[j]]!=B[i][j]){ cerr<<"TAU_INVARIANCE_FAIL\n"; return 11; }
    }

    vector<pair<int,int>> pairs;
    vector<char> used(n,0); used[fixed[0]]=1;
    for(int i=0;i<n;i++) if(!used[i]){
        int j=tau[i];
        int a=min(i,j), b=max(i,j);
        if(a==b || used[a] || used[b]){ cerr<<"TAU_PAIR_FAIL\n"; return 12; }
        pairs.push_back({a,b}); used[a]=used[b]=1;
    }
    if(pairs.size()!=199){ cerr<<"TAU_PAIR_COUNT_FAIL\n"; return 13; }

    // Integer congruence basis: fixed vector, then e_i+e_tau(i) (even);
    // and e_i-e_tau(i) (odd). Since B commutes with tau, cross blocks vanish.
    vector<vector<cpp_int>> E(200, vector<cpp_int>(200));
    vector<vector<cpp_int>> O(199, vector<cpp_int>(199));
    int f=fixed[0];
    E[0][0]=B[f][f];
    for(int a=0;a<199;a++){
        auto [i,ti]=pairs[a];
        E[0][a+1]=E[a+1][0]=B[f][i]+B[f][ti];
        for(int b=0;b<199;b++){
            auto [j,tj]=pairs[b];
            E[a+1][b+1]=B[i][j]+B[i][tj]+B[ti][j]+B[ti][tj];
            O[a][b]=B[i][j]-B[i][tj]-B[ti][j]+B[ti][tj];
            cpp_int cross=B[i][j]-B[i][tj]+B[ti][j]-B[ti][tj];
            if(cross!=0){ cerr<<"EVEN_ODD_CROSS_FAIL\n"; return 14; }
        }
    }

    unsigned ebits=0, obits=0;
    if(!bareiss_spd(E,ebits)){ cerr<<"EVEN_BLOCK_NOT_SPD\n"; return 15; }
    if(!bareiss_spd(O,obits)){ cerr<<"ODD_BLOCK_NOT_SPD\n"; return 16; }

    long long lhs=9LL*t*t, rhs=4LL*p;
    if(lhs>rhs){ cerr<<"THRESHOLD_FAIL\n"; return 17; }

    cout<<"P="<<p<<"\n";
    cout<<"LOCALIZATION_N="<<n<<"\n";
    cout<<"TAU_FIXED_VERTICES="<<fixed.size()<<"\n";
    cout<<"TAU_TWO_CYCLES="<<pairs.size()<<"\n";
    cout<<"TAU_NONEDGE_ORBITS="<<orbit_count<<"\n";
    cout<<"EDGE_PAIRS="<<edge_pairs<<"\n";
    cout<<"NONEDGE_PAIRS="<<nonedge_pairs<<"\n";
    cout<<"DUAL_T="<<t<<"\n";
    cout<<"SCALE="<<scale<<"\n";
    cout<<"THRESHOLD_SQUARED_CHECK="<<lhs<<"<="<<rhs<<"\n";
    cout<<"EVEN_BLOCK_DIM=200\n";
    cout<<"ODD_BLOCK_DIM=199\n";
    cout<<"EVEN_BAREISS_SPD=PASS\n";
    cout<<"ODD_BAREISS_SPD=PASS\n";
    cout<<"EVEN_FINAL_PIVOT_BITS="<<ebits<<"\n";
    cout<<"ODD_FINAL_PIVOT_BITS="<<obits<<"\n";
    cout<<"CERTIFICATE=PASS\n";
    return 0;
}
